const { createClient } = require('./node_modules/@supabase/supabase-js');
const supabase = createClient(process.env.SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY);

// Kinki region university IDs (excluding osaka, osaka_metro)
const kinki = ['kyoto', 'kyoto_tech', 'kyoto_pref_med', 'kyoto_pref', 'kobe', 'nara_women', 'wakayama_med', 'mie'];

async function main() {
  // Get documents for these universities with math subject
  const { data: docs, error } = await supabase
    .from('kakomon_documents')
    .select('id, university_id, year, subject, subject_variant, exam_type, content_type, pdf_storage_path')
    .in('university_id', kinki)
    .like('subject', 'math%')
    .order('university_id')
    .order('year');

  if (error) { console.error(error); return; }
  console.log('=== Math documents in Kinki ===');
  console.log(JSON.stringify(docs, null, 2));

  // Check questions (splits) for these documents
  if (docs && docs.length > 0) {
    const docIds = docs.map(d => d.id);
    const { data: questions, error: qErr } = await supabase
      .from('kakomon_questions')
      .select('id, document_id, question_number, question_label, split_pdf_path, split_image_path, answer_split_pdf_path, topic_tags')
      .in('document_id', docIds)
      .order('document_id')
      .order('question_number');

    if (qErr) { console.error(qErr); return; }
    console.log('\\n=== Existing questions (splits) ===');
    console.log(JSON.stringify(questions, null, 2));
  }
}
main();
"

